/** 
 * Returns a new  {@link BigtableIO.Read} that will read from the Cloud Bigtable instanceindicated by the given options, and using any other specified customizations. <p>Clones the given  {@link BigtableOptions} builder so that any further changeswill have no effect on the returned  {@link BigtableIO.Read}. <p>Does not modify this object.
 */
public Read withBigtableOptions(BigtableOptions.Builder optionsBuilder){
  checkNotNull(optionsBuilder,"optionsBuilder");
  BigtableOptions options=optionsBuilder.build();
  BigtableOptions.Builder clonedBuilder=options.toBuilder().setDataChannelCount(1);
  BigtableOptions optionsWithAgent=clonedBuilder.setUserAgent(getUserAgent()).build();
  return new Read(optionsWithAgent,tableId,keyRange,filter,bigtableService);
}
